          runtimeType == other.runtimeType &&
          inviterIdentityPubkeyHex == other.inviterIdentityPubkeyHex &&
          groupIdHex == other.groupIdHex &&
          welcomeB64 == other.welcomeB64 &&
          sentAtUnix == other.sentAtUnix;
}

